// 設置基本配置
const config = {
  studentId: 'A123321111',  // 可在此修改學號
  repoOwner: 'ntust2026',
  repoName: 'ntust2026.github.io',
  filePath: 'newsEMBA',
  // githubToken 已移至 Header Auth credential，無需在此設定
};

// 生成日期格式 (YYYYMMDD)
const now = new Date();
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');
const day = String(now.getDate()).padStart(2, '0');
const hour = String(now.getHours()).padStart(2, '0');
const minute = String(now.getMinutes()).padStart(2, '0');
const dateStr = `${year}${month}${day}`;
const timeStr = `${hour}${minute}`;

// 建立檔名 (日期+時分+學號)
const filename = `${dateStr}_${timeStr}_${config.studentId}.html`;

console.log('工作流程配置:', JSON.stringify(config, null, 2));
console.log('當前日期:', dateStr);
console.log('生成的檔名:', filename);

return [{
  json: {
    config: config,
    dateStr: dateStr,
    filename: filename,
    timestamp: now.toISOString()
  }
}];

// 定義所有新聞主題
const topics = [
  '投資理財',
  '生活與時尚', 
  'AI',
  '科技',
  '吃'
];

// 隨機選擇一個主題
const randomTopic = topics[Math.floor(Math.random() * topics.length)];

console.log('選中的主題:', randomTopic);

// 保留之前的配置資訊和所有數據
const prevData = items[0].json;

return [{
  json: {
    ...prevData,
    selectedTopic: randomTopic,
    config: prevData.config,
    filename: prevData.filename
  }
}];

// 取得台灣時間 (UTC+8)
const getTaiwanTime = () => {
  const now = new Date();
  // 轉換到台灣時區
  const taiwanTime = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Taipei' }));
  return taiwanTime;
};

// 處理新聞資料並準備輸出
console.log('========== 輸入資料檢查 ==========');
console.log('items 長度:', items.length);

const inputData = items[0].json;
const articles = inputData.articles;
let selectedTopic = inputData.selectedTopic;

if (!selectedTopic) {
  selectedTopic = '新聞';
}

console.log('找到的主題:', selectedTopic);
console.log('文章數量:', articles ? articles.length : 0);

if (!articles || !Array.isArray(articles) || articles.length === 0) {
  console.log('錯誤：無文章資料');
  throw new Error(`無「${selectedTopic}」相關新聞資料。`);
}

// 篩選有效的新聞
const validArticles = articles
  .filter(article => {
    const hasTitle = article.title && article.title.trim() !== '';
    const hasDescription = article.description && article.description.trim() !== '';
    const hasPublishedAt = article.publishedAt && !isNaN(new Date(article.publishedAt));
    const hasUrl = article.url && article.url.trim() !== '';

    return hasTitle && hasDescription && hasPublishedAt && hasUrl;
  })
  .sort((a, b) => new Date(b.publishedAt) - new Date(a.publishedAt));

console.log('有效文章數量:', validArticles.length);

if (validArticles.length === 0) {
  throw new Error(`無有效的「${selectedTopic}」新聞資料。`);
}

// 選擇最新的文章
const selectedArticle = validArticles[0];

console.log('========== 選中的新聞 ==========');
console.log('標題:', selectedArticle.title);
console.log('URL:', selectedArticle.url);

// 建立輸出資料
const outputData = {
  ...inputData,
  title: selectedArticle.title,
  description: selectedArticle.description,
  url: selectedArticle.url,
  source: selectedArticle.source?.name || '未知來源',
  publishedAt: selectedArticle.publishedAt,
  author: selectedArticle.author || '未知作者',
  urlToImage: selectedArticle.urlToImage || '',
  selectedTopic: selectedTopic,
  processedAt: getTaiwanTime().toISOString(),
  totalArticlesFound: articles.length,
  validArticlesCount: validArticles.length
};

return [{ 
  json: {
    ...outputData,
    config: inputData.config,
    filename: inputData.filename
  }
}];

// 從前一個節點（處理新聞資料）取得資料
const data = items[0].json;

const topic = data.selectedTopic || '新聞';
const description = data.description || '';
const title = data.title || '';
const url = data.url || '';

// 組裝完整的 prompt
const prompt = `你是一個專業的社群媒體內容創作者，擅長將新聞內容改寫成吸引人的 Facebook 貼文。

請根據以下新聞資訊，撰寫一篇適合 Facebook 發布的貼文：

【新聞主題】${topic}
【新聞標題】${title}
【新聞描述】${description}
【新聞網址】${url}

【建議分享內容格式：】

今天小編看了一些新聞，裡面最值得我重視的是這一篇:

這消息真的讓人眼睛一亮！你是否也覺得在繁忙的生活節奏中，總需要來點讓人耳目一新的話題呢？

今天看到關於「${topic}」的最新動態，其實這件事背後影響的範圍比想像中還要廣！簡單來說，「${description}」。聽起來是不是覺得生活周遭又多了一個值得關注的重點？小編看完後覺得這不僅僅是資訊的更新，更是我們這代人需要稍微留心一下的趨勢呢！

你們對這個話題有什麼看法嗎？是覺得很有感，還是有什麼特別的觀察？快來留言區跟我分享，我們一起討論討論！如果你也覺得這篇內容很有價值，記得分享給身邊的朋友，讓大家一起跟上這波熱門話題！

#${topic} #熱門話題 #生活觀察 #最新資訊 #趨勢分享

📰 新聞標題：${title}
🔗 完整報導：${url}

---

請依照上述格式和風格撰寫貼文，但可以修改整體結構，要保持親切、口語化、引人入勝的特色。`;

return [{
  json: {
    ...data,  // 把原本的資料都帶過去
    aiPrompt: prompt
  }
}];

// 生成 HTML 內容
// 注意：本節點上游只有「AI 撰寫貼文」，新聞資料要從前面節點取
const data = $('處理新聞資料').item.json;
const config = $('設置配置和檔案名').item.json.config;
const facebookPost = items[0]?.json.output || $('AI 撰寫貼文').item.json.output || '貼文內容生成失敗';

// 格式化日期
const publishDate = new Date(data.publishedAt).toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });
const generatedDate = new Date(data.processedAt).toLocaleString('zh-TW', { timeZone: 'Asia/Taipei' });

// HTML 樣式設計
const htmlContent = `<!DOCTYPE html>
<html lang="zh-TW">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>${data.title}</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Noto Sans TC', 'Microsoft JhengHei', sans-serif;
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            min-height: 100vh;
            padding: 2rem;
            color: #333;
        }

        .container {
            max-width: 900px;
            margin: 0 auto;
            background: white;
            border-radius: 12px;
            box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
            overflow: hidden;
        }

        .header {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 3rem 2rem;
            text-align: center;
        }

        .header h1 {
            font-size: 2.5rem;
            margin-bottom: 0.5rem;
            line-height: 1.3;
        }

        .header .category {
            display: inline-block;
            background: rgba(255, 255, 255, 0.3);
            padding: 0.5rem 1rem;
            border-radius: 20px;
            font-size: 0.9rem;
            margin-top: 1rem;
        }

        .meta-info {
            background: #f8f9fa;
            padding: 1.5rem 2rem;
            border-bottom: 1px solid #eee;
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 1rem;
        }

        .meta-item {
            font-size: 0.9rem;
        }

        .meta-item strong {
            color: #667eea;
            display: block;
            margin-bottom: 0.3rem;
        }

        .content {
            padding: 3rem 2rem;
        }

        .content h2 {
            color: #667eea;
            margin-bottom: 1.5rem;
            font-size: 1.5rem;
        }

        .news-title {
            font-size: 1.3rem;
            color: #222;
            margin-bottom: 1rem;
            line-height: 1.5;
        }

        .news-description {
            color: #555;
            line-height: 1.8;
            margin-bottom: 2rem;
            padding: 1rem;
            background: #f0f3f9;
            border-left: 4px solid #667eea;
        }

        .facebook-post {
            background: #f8f9fa;
            padding: 2rem;
            border-radius: 8px;
            margin: 2rem 0;
            border: 2px dashed #667eea;
        }

        .facebook-post h3 {
            color: #667eea;
            margin-bottom: 1rem;
            font-size: 1.1rem;
        }

        .post-content {
            color: #333;
            line-height: 1.8;
            white-space: pre-wrap;
            word-wrap: break-word;
        }

        .source-link {
            margin-top: 2rem;
            padding-top: 2rem;
            border-top: 2px solid #eee;
        }

        .source-link a {
            display: inline-block;
            background: #667eea;
            color: white;
            padding: 0.8rem 1.5rem;
            border-radius: 6px;
            text-decoration: none;
            transition: background 0.3s;
            margin-top: 1rem;
        }

        .source-link a:hover {
            background: #764ba2;
        }

        .footer {
            background: #f8f9fa;
            padding: 2rem;
            text-align: center;
            border-top: 1px solid #eee;
            font-size: 0.85rem;
            color: #666;
        }

        .generated-badge {
            display: inline-block;
            background: #e8f1ff;
            color: #667eea;
            padding: 0.5rem 1rem;
            border-radius: 20px;
            font-size: 0.85rem;
            margin-top: 1rem;
        }

        @media (max-width: 768px) {
            .header h1 {
                font-size: 1.8rem;
            }

            .meta-info {
                grid-template-columns: 1fr;
            }

            .content {
                padding: 1.5rem;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <div class="header">
            <h1>${data.title}</h1>
            <div style="display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap;">
                <span class="category">📰 ${data.selectedTopic}</span>
                <span class="category" style="background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);">🎓 ${config.studentId}</span>
            </div>
        </div>

        <div class="meta-info">
            <div class="meta-item">
                <strong>新聞來源</strong>
                ${data.source}
            </div>
            <div class="meta-item">
                <strong>作者</strong>
                ${data.author}
            </div>
            <div class="meta-item">
                <strong>發布時間</strong>
                ${publishDate}
            </div>
            <div class="meta-item">
                <strong>內容分類</strong>
                ${data.selectedTopic}
            </div>
        </div>

        <div class="content">
            <h2>📌 新聞摘要</h2>
            <div class="news-description">
                ${data.description}
            </div>

            <h2>📱 Facebook 貼文</h2>
            <div class="facebook-post">
                <h3>建議分享內容：</h3>
                <div class="post-content">${facebookPost}</div>
            </div>

            <div class="source-link">
                <strong>完整新聞報導：</strong><br>
                <a href="${data.url}" target="_blank">閱讀完整文章 →</a>
            </div>
        </div>

        <div class="footer">
            <p>日報系統自動生成</p>
            <p>生成時間：${generatedDate}</p>
            <span class="generated-badge">學號: ${config.studentId}</span>
        </div>
    </div>
</body>
</html>`;

console.log('HTML 文件已生成');
console.log('確認 config 存在:', !!data.config);
console.log('確認 filename 存在:', !!data.filename);

// 確保 config 和 filename 被保留
const outputData = {
  ...data,
  htmlContent: htmlContent,
  facebookPost: facebookPost,
  config: data.config,
  filename: data.filename
};

return [{
  json: outputData
}];

// 準備 GitHub API 上傳的資料
const data = items[0].json;
// 備援：若上游遺失 config/filename，從原始節點取
const htmlContent = data.htmlContent;
let filename = data.filename || $('設置配置和檔案名').item.json.filename;
let config = data.config || $('設置配置和檔案名').item.json.config;

console.log('=== 準備 GitHub 上傳 ===');
console.log('htmlContent 存在:', !!htmlContent);
console.log('filename:', filename);
console.log('config 存在:', !!config);

// 如果 config 不存在，建立備用
if (!config) {
  console.log('⚠️ config 不存在，使用備用');
  config = {
    repoOwner: 'ntust2026',
    repoName: 'ntust2026.github.io',
    filePath: 'news',
    // githubToken 已移至 Header Auth credential，無需在此設定
  };
}

// 如果 filename 不存在，生成一個
if (!filename) {
  console.log('⚠️ filename 不存在，自動生成');
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');
  const hour = String(now.getHours()).padStart(2, '0');
  const minute = String(now.getMinutes()).padStart(2, '0');
  const dateStr = `${year}${month}${day}`;
  const timeStr = `${hour}${minute}`;
  const studentId = config?.studentId || 'A123456789';
  filename = `${dateStr}_${timeStr}_${studentId}.html`;
}

// 驗證
if (!htmlContent) {
  throw new Error('❌ 缺少 htmlContent');
}

// 轉換 HTML 為 Base64
const base64Content = Buffer.from(htmlContent).toString('base64');

console.log('✅ 準備完成');
console.log('檔案名稱:', filename);
console.log('Repository:', `${config.repoOwner}/${config.repoName}`);

return [{
  json: {
    ...data,
    base64Content: base64Content,
    uploadPath: `${config.filePath}/${filename}`,
    uploadUrl: `https://api.github.com/repos/${config.repoOwner}/${config.repoName}/contents/${config.filePath}/${filename}`,
    config: config,
    filename: filename
  }
}];

// 取得台灣時間 (UTC+8)
const getTaiwanTime = () => {
  const now = new Date();
  // 轉換到台灣時區
  const taiwanTime = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Taipei' }));
  return taiwanTime;
};

// 完成並顯示結果
const data = $('準備 GitHub 上傳').item.json;
const result = items[0].json;

console.log('========== 上傳結果 ==========');
console.log('狀態碼:', result.statusCode || result.status);
console.log('上傳的檔案:', data.filename);
console.log('Repository:', `${data.config.repoOwner}/${data.config.repoName}`);

const success = result.statusCode === 201 || result.status === 201;

return [{
  json: {
    success: success,
    filename: data.filename,
    dateStr: data.dateStr,
    studentId: data.config.studentId,
    topic: data.selectedTopic,
    newsTitle: data.title,
    fileUrl: `https://github.com/${data.config.repoOwner}/${data.config.repoName}/blob/main/${data.config.filePath}/${data.filename}`,
    rawUrl: `https://raw.githubusercontent.com/${data.config.repoOwner}/${data.config.repoName}/main/${data.config.filePath}/${data.filename}`,
    message: success ? '✅ 成功上傳到 GitHub!' : '❌ 上傳失敗，請檢查 GitHub Token',
    timestamp: getTaiwanTime().toISOString()
  }
}];
